select * FROM vik_noeud;

update vik_noeud set lig_num= trim(lig_num);

select * from vik_etape;

select * from vik_noeud;


SELECT 
    n.LIG_NUM,
    c_dep.COM_NOM AS commune_depart,
    c_arr.COM_NOM AS commune_arrivee,
    SUM(n.NOE_DUREE_PROCHAIN)  / 60 AS duree_totale_minutes
FROM VIK_NOEUD n
JOIN VIK_LIGNE l ON l.LIG_NUM = n.LIG_NUM
JOIN VIK_COMMUNE c_dep ON c_dep.COM_CODE_INSEE = l.COM_CODE_INSEE_DEBU
JOIN VIK_COMMUNE c_arr ON c_arr.COM_CODE_INSEE = l.COM_CODE_INSEE_TERM
WHERE c_dep.COM_NOM = 'Caen'
  AND c_arr.COM_NOM = 'Granville'
GROUP BY n.LIG_NUM, c_dep.COM_NOM, c_arr.COM_NOM
ORDER BY duree_totale_minutes ASC
FETCH FIRST 1 ROWS ONLY;


---------------------------------------

SELECT 
    TRIM(n.LIG_NUM) AS LIG_NUM,
    c_dep.COM_NOM AS commune_depart,
    c_arr.COM_NOM AS commune_arrivee,
    ROUND(SUM(n.NOE_DISTANCE_PROCHAIN), 1) AS distance_totale_km
FROM (
    SELECT DISTINCT LIG_NUM, COM_CODE_INSEE_ARRET, COM_CODE_INSEE_SUIVANT, NOE_DISTANCE_PROCHAIN
    FROM VIK_NOEUD
) n
JOIN VIK_LIGNE l ON TRIM(l.LIG_NUM) = TRIM(n.LIG_NUM)
JOIN VIK_COMMUNE c_dep ON c_dep.COM_CODE_INSEE = l.COM_CODE_INSEE_DEBU
JOIN VIK_COMMUNE c_arr ON c_arr.COM_CODE_INSEE = l.COM_CODE_INSEE_TERM
WHERE c_dep.COM_NOM = 'Caen'
  AND c_arr.COM_NOM = 'Granville'
GROUP BY TRIM(n.LIG_NUM), c_dep.COM_NOM, c_arr.COM_NOM
ORDER BY distance_totale_km ASC
FETCH FIRST 1 ROWS ONLY;

UPDATE VIK_CLIENT SET CLI_NUM = ROWNUM;
