SELECT COM_CODE_INSEE_ARRET, COM_CODE_INSEE_SUIVANT, 
TO_CHAR(NOE_HEURE_PASSAGE,'HH24:MI') AS heure
FROM VIK_NOEUD
WHERE TRIM(LIG_NUM) = '10A'
ORDER BY COM_CODE_INSEE_ARRET, NOE_HEURE_PASSAGE;